def n(x: int) -> str:
    return f"{x:,}".replace(",", " ")


def ps(*xs: str) -> str:
    return "".join(f"<p>{x}</p>" for x in xs)


def ul(*xs: str) -> str:
    return "<ul>" + "".join(f"<li>{x}</li>" for x in xs) + "</ul>"


