DOCS = {"priv": PRIV, "terms": TERMS, "offer": OFFER}
BY_SLUG = {d["slug"]: (k, d) for k, d in DOCS.items()}


def as_json(key: str) -> dict:
    d = DOCS[key]
    return {"t": d["t"], "d": d["d"], "slug": d["slug"], "s": [list(x) for x in d["s"]]}
